[{"role": "user", "content": "You are a precise API argument extractor. You receive a Tool Definition and a User Query. You must output a valid JSON object containing the arguments based on the schema. Note that you should always output a single JSON object, not a list of JSON objects. Do not include markdown formatting. ### Tool Definition
{
  "tool_name": "VALUE SERP",
  "description": "The Google Search Parameters are applicable when making a request to the Search API to retrieve Google search results for a given search term. The search term is specified in the q parameter. The location your search is run from is determined by the location parameter, which can be populated with a full_name value from the Locations API.",
  "required_parameters": [
    {
      "name": "q",
      "type": "STRING",
      "description": "The keyword you want to use to perform the search."
    }
  ],
  "optional_parameters": [
